import { CodeBlock } from '@/react/components/ui/CodeBlock'
import { DocsFields, type DocsField } from '@/react/components/site/DocsFields'
import { DocsInline } from '@/react/components/site/DocsInline'
import { DocsTable } from '@/react/components/site/DocsTable'
import { cn } from '@/react/lib/cn'

// A docs page's body, block by block (docs/Blocks.vue): paragraphs, headings (steps are the smaller ones), lists led
// by a red square, callouts (a warning on the wash), tables, code in the one code window, an endpoint's fields, and the
// link cards, each in the double rule with a pixel pattern that turns red under the pointer. Text takes `code`,
// **bold** and [links](href). `wide` drops the 880px measure, for a page of cards. Follows the theme (data-theme).
export type DocsBlock =
  | { kind: 'p', text: string }
  | { kind: 'h2' | 'h3', id: string, text: string }
  | { kind: 'list', items: string[] }
  | { kind: 'callout', tone: 'note' | 'warning' | 'caution' | (string & {}), text: string }
  | { kind: 'table', head?: string[], rows: string[][] }
  | { kind: 'code', samples: { label: string, code: string }[] }
  | { kind: 'cards', items: { title: string, body: string, href: string }[] }
  | { kind: 'fields', media?: string, fields: DocsField[] }
export type { DocsField }

export interface DocsBlocksProps {
  blocks: DocsBlock[]
  wide?: boolean
  className?: string
}

// The hero tabs' pixel patterns, each a path on a 16px square of 2px cells, centred.
const pattern = (on: (x: number, y: number) => boolean) => {
  const lit: [number, number][] = []
  for (let y = 0; y < 8; y++) for (let x = 0; x < 8; x++) if (on(x, y)) lit.push([x, y])
  const ox = (16 - (Math.max(...lit.map(c => c[0])) + Math.min(...lit.map(c => c[0])) + 1) * 2) / 2
  const oy = (16 - (Math.max(...lit.map(c => c[1])) + Math.min(...lit.map(c => c[1])) + 1) * 2) / 2
  return lit.map(([x, y]) => `M${x * 2 + ox} ${y * 2 + oy}h2v2h-2Z`).join('')
}
const PATTERNS = [
  pattern((x, y) => x % 2 === 0 && y % 2 === 0),
  pattern((x, y) => (x + y) % 3 === 0),
  pattern((x, y) => (Math.floor(x / 2) + Math.floor(y / 2)) % 2 === 0),
  pattern((_, y) => y % 2 === 0),
]

function Block({ b }: { b: DocsBlock }) {
  switch (b.kind) {
    case 'h2': return <h2 id={b.id} className="mt-10 scroll-mt-28 text-docs-heading tracking-tight">{b.text}</h2>
    case 'h3': return <h3 id={b.id} className="mt-4 scroll-mt-28 text-heading-4 font-medium">{b.text}</h3>
    case 'p': return <p className="text-input leading-7 text-fg-muted"><DocsInline text={b.text} /></p>
    case 'list':
      return (
        <ul className="flex flex-col gap-2 text-input leading-7 text-fg-muted">
          {b.items.map(t => (
            <li key={t} className="flex gap-3">
              <span aria-hidden="true" className="mt-2.75 size-1.5 shrink-0 bg-edge-accent" />
              <span><DocsInline text={t} /></span>
            </li>
          ))}
        </ul>
      )
    case 'callout':
      return (
        <div className="ds-docs-callout flex gap-3 px-4 py-3 type-body-lg" data-tone={b.tone}>
          <span aria-hidden="true" className="mt-2.25 size-1.5 shrink-0 bg-edge-accent" />
          <span><DocsInline text={b.text} /></span>
        </div>
      )
    case 'table': return <DocsTable head={b.head} rows={b.rows} />
    case 'fields':
      return (
        <div>
          {b.media && <p className="-mt-2 mb-1 type-code-sm text-fg-muted" dir="ltr">{b.media}</p>}
          <DocsFields fields={b.fields} />
        </div>
      )
    case 'code': return <CodeBlock className="my-2" samples={b.samples.length > 1 ? b.samples : undefined} code={b.samples.length > 1 ? undefined : b.samples[0]?.code} label={b.samples.length > 1 ? undefined : b.samples[0]?.label} />
    case 'cards':
      return (
        <ul className="my-4 grid gap-6 sm:grid-cols-2">
          {b.items.map((c, j) => (
            <li key={c.title} className="border border-edge-strong outline outline-offset-4 outline-edge-strong">
              <a href={c.href} className="ds-docs-card flex h-full flex-col gap-4 p-5">
                <svg width="16" height="16" viewBox="0 0 16 16" shapeRendering="crispEdges" aria-hidden="true" className="ds-docs-card-mark"><path d={PATTERNS[j % 4]} fill="currentColor" /></svg>
                <span>
                  <span className="block type-heading-3">{c.title}</span>
                  <span className="mt-1 block type-body text-fg-muted"><DocsInline text={c.body} /></span>
                </span>
              </a>
            </li>
          ))}
        </ul>
      )
  }
}

export function DocsBlocks({ blocks, wide, className }: DocsBlocksProps) {
  return (
    <div data-ds="docs-blocks" className={cn('flex flex-col gap-5 text-fg', !wide && 'max-w-220', className)}>
      <style href="ds-docs-blocks" precedence="ds">{css}</style>
      {blocks.map((b, i) => <Block key={i} b={b} />)}
    </div>
  )
}

export default DocsBlocks

const css = `
.ds-docs-callout { border: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface-subtle); color: var(--ds-color-fg); }
.ds-docs-callout:is([data-tone="warning"], [data-tone="caution"]) { border-color: color-mix(in srgb, var(--ds-color-edge-accent) 30%, transparent); background: var(--ds-color-surface-danger); }
.ds-docs-card { transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-docs-card-mark { color: var(--ds-color-fg-faint); transition: color var(--ds-duration-micro) var(--ds-easing-standard); }
@media (hover: hover) and (pointer: fine) {
  .ds-docs-card:hover { background: var(--ds-color-surface-subtle); }
  .ds-docs-card:hover .ds-docs-card-mark { color: var(--ds-color-edge-accent); }
}
`

import { Fragment } from 'react'

// A line of docs text with its `code`, **bold** and [links](href) set (docs/Inline.vue): code in the mono on the
// paper, bold in ink, links in the red with a quiet underline that turns full under the pointer.
type Part = { kind: 'text' | 'code' | 'bold', text: string } | { kind: 'link', text: string, href: string }

export function docsParts(text: string): Part[] {
  const out: Part[] = []
  const re = /`([^`]+)`|\[([^\]]+)\]\(([^)]+)\)|\*\*(.+?)\*\*/g
  let last = 0
  for (const m of text.matchAll(re)) {
    if (m.index > last) out.push({ kind: 'text', text: text.slice(last, m.index) })
    if (m[1] !== undefined) out.push({ kind: 'code', text: m[1] })
    else if (m[4] !== undefined) out.push({ kind: 'bold', text: m[4] })
    else out.push({ kind: 'link', text: m[2]!, href: m[3]! })
    last = m.index + m[0].length
  }
  if (last < text.length) out.push({ kind: 'text', text: text.slice(last) })
  return out
}

export interface DocsInlineProps { text: string }

export function DocsInline({ text }: DocsInlineProps) {
  return (
    <>
      <style href="ds-docs-inline" precedence="ds">{css}</style>
      {docsParts(text).map((p, i) => (p.kind === 'code'
        ? <code key={i} data-ds="docs-inline" dir="ltr" className="ds-docs-code">{p.text}</code>
        : p.kind === 'link'
          ? <a key={i} data-ds="docs-inline" href={p.href} className="ds-docs-link">{p.text}</a>
          : p.kind === 'bold'
            ? <strong key={i} data-ds="docs-inline" className="font-medium text-fg">{p.text}</strong>
            : <Fragment key={i}>{p.text}</Fragment>))}
    </>
  )
}

export default DocsInline

const css = `
.ds-docs-code { border: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface-subtle); padding: 0 var(--ds-space-xs); font-family: var(--ds-font-code); font-size: 0.86em; }
.ds-docs-link { color: var(--ds-color-edge-accent); text-decoration: underline; text-decoration-color: color-mix(in srgb, var(--ds-color-edge-accent) 40%, transparent); text-underline-offset: 3px; transition: text-decoration-color var(--ds-duration-micro) var(--ds-easing-standard); }
@media (hover: hover) and (pointer: fine) { .ds-docs-link:hover { text-decoration-color: var(--ds-color-edge-accent); } }
`

import { DocsInline } from '@/react/components/site/DocsInline'
import { cn } from '@/react/lib/cn'

// An endpoint's parameters or fields (docs/Fields.vue), one ruled row each: the name in the mono, its type and
// "required" or its default beside it, then what it is and its limits. A field's own fields sit under it behind a
// toggle, in the same rows a step in; the toggle's plus turns to a minus when open.
export type DocsField = { name: string, type: string, required?: boolean, default?: string, text?: string, notes?: string[], children?: DocsField[] }

export interface DocsFieldsProps {
  fields: DocsField[]
  nested?: boolean
  className?: string
}

export function DocsFields({ fields, nested, className }: DocsFieldsProps) {
  return (
    <>
      <style href="ds-docs-fields" precedence="ds">{css}</style>
      <ul data-ds="docs-fields" className={cn('ds-docs-params flex flex-col', nested && 'border-s border-edge ps-4', className)}>
        {fields.map(f => (
          <li key={f.name} className="py-4">
            <p className="flex flex-wrap items-center gap-x-2 gap-y-1 type-code" dir="ltr">
              <span className="font-medium text-fg">{f.name}</span>
              <span className="ds-docs-tag">{f.type}</span>
              {f.required && <span className="ds-docs-tag" data-required="">required</span>}
              {f.default !== undefined && <span className="ds-docs-tag">{`default: ${f.default}`}</span>}
            </p>
            {f.text && <p className="mt-2 type-body-lg text-fg-muted"><DocsInline text={f.text} /></p>}
            {f.notes?.map(n => <p key={n} className="mt-1.5 type-ui text-fg-muted"><DocsInline text={n} /></p>)}
            {f.children && (
              <details className="ds-docs-more mt-3">
                <summary className="ds-docs-btn inline-flex h-7 cursor-pointer list-none items-center gap-1.5 px-2.5 text-meta leading-4">
                  <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.2" aria-hidden="true" className="ds-docs-sign"><path d="M5 1.5v7M1.5 5h7" /></svg>
                  {`${f.children.length} ${f.children.length === 1 ? 'field' : 'fields'}`}
                </summary>
                <DocsFields fields={f.children} nested className="mt-2" />
              </details>
            )}
          </li>
        ))}
      </ul>
    </>
  )
}

export default DocsFields

const css = `
.ds-docs-params > li + li { border-top: var(--ds-border-hairline) solid var(--ds-color-edge); }
.ds-docs-tag { border: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface-subtle); padding: 0 calc(var(--ds-space-xs) + 1px); font-size: var(--ds-text-caption); line-height: 18px; color: var(--ds-color-fg-muted); }
.ds-docs-tag[data-required] { border-color: color-mix(in srgb, var(--ds-color-edge-accent) 40%, transparent); background: var(--ds-color-surface-danger); color: var(--ds-color-edge-accent); }
.ds-docs-btn { border: var(--ds-border-hairline) solid var(--ds-color-edge); color: var(--ds-color-fg); transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
@media (hover: hover) and (pointer: fine) { .ds-docs-btn:hover { background: var(--ds-color-surface-subtle); } }
.ds-docs-more summary::-webkit-details-marker { display: none; }
.ds-docs-more[open] > summary .ds-docs-sign path { d: path("M1.5 5h7"); }
`

import { DocsInline } from '@/react/components/site/DocsInline'
import { cn } from '@/react/lib/cn'

// A docs table (docs/Table.vue): ruled rows under a paper head, or none for a key-value table, whose first column is
// set in ink. Cells take DocsInline. It scrolls sideways in its own frame on a phone.
export interface DocsTableProps {
  head?: string[]
  rows: string[][]
  label?: string
  className?: string
}

export function DocsTable({ head, rows, label, className }: DocsTableProps) {
  return (
    <>
      <style href="ds-docs-table" precedence="ds">{css}</style>
      <div data-ds="docs-table" className={cn('ds-docs-table fade-x overflow-x-auto border border-edge', className)} role="region" aria-label={label ?? head?.join(', ') ?? 'table'} tabIndex={0}>
        <table className="w-full text-left type-body">
          {head && (
            <thead className="bg-surface-subtle text-fg-muted">
              <tr>{head.map(h => <th key={h} className="px-4 py-3 text-meta font-normal whitespace-nowrap">{h}</th>)}</tr>
            </thead>
          )}
          <tbody>
            {rows.map(row => (
              <tr key={row[0]}>
                {row.map((cell, c) => <td key={c} className={cn('px-4 py-3 align-top', c === 0 ? 'min-w-35 text-fg' : 'text-fg-muted')}><DocsInline text={cell} /></td>)}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  )
}

export default DocsTable

const css = `
.ds-docs-table tr + tr, .ds-docs-table thead + tbody tr:first-child { border-top: var(--ds-border-hairline) solid var(--ds-color-edge); }
`

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

